pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 dep) internal {
        dep = bound(dep, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= dep);
        try c.deposit{value: dep}() {} catch { return; }
        bool reverted1;
        try c.withdrawAll() { reverted1 = false; } catch { reverted1 = true; }
        uint balBefore = address(c).balance;
        bool reverted2;
        try c.withdrawAll() { reverted2 = false; } catch { reverted2 = true; }
        assertTrue(!reverted1 || (address(c).balance == balBefore));
    }

    function testFuzz_run(uint256 dep) public {
        _run(dep);
    }

    receive() external payable {}
}
